package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigFraction_pow_TriageGen0Test {

    @Test
    public void testPowPositiveExponent() {
        // Test (2/3)^2 = 4/9
        BigFraction fraction = new BigFraction(2, 3);
        BigFraction result = fraction.pow(new BigInteger("2"));

        Assert.assertEquals(new BigFraction(4, 9), result);
        Assert.assertEquals(new BigInteger("4"), result.getNumerator());
        Assert.assertEquals(new BigInteger("9"), result.getDenominator());
    }

    @Test
    public void testPowZeroExponent() {
        // Test (2/3)^0 = 1/1
        BigFraction fraction = new BigFraction(2, 3);
        BigFraction result = fraction.pow(BigInteger.ZERO);

        Assert.assertEquals(new BigFraction(1, 1), result);
        Assert.assertEquals(BigInteger.ONE, result.getNumerator());
        Assert.assertEquals(BigInteger.ONE, result.getDenominator());
    }

    @Test
    public void testPowNegativeExponent() {
        // Test (2/3)^(-2) = (3/2)^2 = 9/4
        BigFraction fraction = new BigFraction(2, 3);
        BigFraction result = fraction.pow(new BigInteger("-2"));

        Assert.assertEquals(new BigFraction(9, 4), result);
        Assert.assertEquals(new BigInteger("9"), result.getNumerator());
        Assert.assertEquals(new BigInteger("4"), result.getDenominator());
    }

    @Test
    public void testPowOneExponent() {
        // Test (5/7)^1 = 5/7
        BigFraction fraction = new BigFraction(5, 7);
        BigFraction result = fraction.pow(BigInteger.ONE);

        Assert.assertEquals(new BigFraction(5, 7), result);
    }

    @Test
    public void testPowLargeExponent() {
        // Test (1/2)^10 = 1/1024
        BigFraction fraction = new BigFraction(1, 2);
        BigFraction result = fraction.pow(BigInteger.valueOf(10));

        Assert.assertEquals(new BigFraction(1, 1024), result);
    }

    @Test
    public void testPowNegativeExponentWithNumeratorOne() {
        // Test (1/3)^(-3) = 3^3 / 1^3 = 27/1
        BigFraction fraction = new BigFraction(1, 3);
        BigFraction result = fraction.pow(new BigInteger("-3"));

        Assert.assertEquals(new BigFraction(27, 1), result);
        Assert.assertEquals(BigInteger.valueOf(27), result.getNumerator());
        Assert.assertEquals(BigInteger.ONE, result.getDenominator());
    }

    @Test
    public void testPowNegativeExponentWithDenominatorOne() {
        // Test (3/1)^(-2) = 1^2 / 3^2 = 1/9
        BigFraction fraction = new BigFraction(3, 1);
        BigFraction result = fraction.pow(new BigInteger("-2"));

        Assert.assertEquals(new BigFraction(1, 9), result);
        Assert.assertEquals(BigInteger.ONE, result.getNumerator());
        Assert.assertEquals(BigInteger.valueOf(9), result.getDenominator());
    }
}
